"""V4: dois experimentos distintos, diagnostico novo e revisao humana declarada."""
from copy import deepcopy
import json
from .writing import pt,pct,pp,table
from .diagnostic_report_v4 import narrative


def manuscript(v3,metrics,controlled,diagnostic,review,example,human):
    require_human(human)
    d=deepcopy(v3);d['draft_notice']='RASCUNHO V4 PARA REVISÃO AUTORAL — NÃO SUBMETIDO'
    refs=[b for b in v3['blocks'] if b['kind']=='reference'];cm={r['condition']:r for r in controlled['conditions']}
    original=metrics['paired_C_minus_B'];effect=controlled['paired_Ceq_minus_Beq']
    om={r['condition']:r for r in metrics['conditions']};errors={(r['condition'],r['type']):r['count'] for r in controlled['errors']}
    dg={(r['selected_on'],r['max_tokens']):r for r in diagnostic['groups']};lo=dg['old_empty',2048];hi=dg['old_empty',4096]
    d['abstract_pt']=(f'Avaliamos uma arquitetura de consultas ambientais em português sobre MapBiomas Coleção 11, no RN, em 2015 e 2025. O autor declarou revisar as 120 perguntas de teste e os 88 gabaritos quantitativos, sem correções. O experimento original avalia interpretação, validação, execução e resposta: sistema com executor versus modelo com tabelas, sob contratos distintos, diferiram {pp(original["difference_C_minus_B"])} pontos percentuais. Um controle exploratório reutiliza 88 consultas com plano de referência fixo e mesmo contrato final; apenas C_eq recebe cálculo do executor. C_eq obteve {cm["C_eq"]["correct"]}/{cm["C_eq"]["cases"]} e B_eq {cm["B_eq"]["correct"]}/{cm["B_eq"]["cases"]}, diferença {pp(effect["difference_C_minus_B"])} pontos, IC95% [{pp(effect["ci95"][0])}; {pp(effect["ci95"][1])}]. A diferença corresponde a falhas de emissão/contrato, sem erros nas respostas emitidas. Reexecuções instrumentadas investigam o limite de saída, sem recuperar metadados históricos perdidos. Os 100% de C_eq são condicionados ao plano fornecido, sem evidência de generalização para perguntas inéditas ou verdade de campo.')
    d['abstract_en']=(f'We evaluate a Portuguese environmental-query architecture over MapBiomas Collection 11 in Rio Grande do Norte, Brazil, for 2015 and 2025. The author reported reviewing all 120 test questions and 88 quantitative references without corrections. The original experiment evaluates interpretation, validation, execution and response: the executor system and tables-based model differed by {100*original["difference_C_minus_B"]:.2f} percentage points under different contracts. An exploratory control reuses 88 queries with fixed reference plans and identical final contracts; only C_eq receives executor results. C_eq achieved {cm["C_eq"]["correct"]}/{cm["C_eq"]["cases"]} and B_eq {cm["B_eq"]["correct"]}/{cm["B_eq"]["cases"]}, a {100*effect["difference_C_minus_B"]:.2f}-point difference, 95% CI [{100*effect["ci95"][0]:.2f}; {100*effect["ci95"][1]:.2f}]. The difference comprises emission/contract failures, with no errors among emitted answers. Instrumented replays investigate the output budget without recovering missing historical metadata. C_eq’s 100% is conditional on supplied plans, not evidence of generalization to unseen questions or field truth.')
    blocks=[]
    def h(text):blocks.append({'kind':'heading','text':text})
    def p(text,**kw):blocks.append({'kind':'paragraph','text':text,**kw})
    h('1. INTRODUÇÃO')
    p('Consultar mapas por linguagem natural exige resolver território, classe, suporte e métrica. Respostas fluentes podem ocultar escolhas incorretas de denominador. O histórico do MapBiomas [1] contextualiza o produto, sem certificar a revisão utilizada ou sua acurácia local.')
    p('Program of Thoughts [2] separa raciocínio linguístico e cálculo. GeoGPT [3] conecta linguagem natural a ferramentas SIG; FloodSQL-Bench [4] aborda Text-to-SQL geoespacial e avalia similaridade de consultas, sem execução no protocolo citado. Toolformer [5] aprende chamadas de APIs e ReAct [6] intercala ações e raciocínio. Não reivindicamos inaugurar essas interfaces: avaliamos uma arquitetura em português, com operações restritas, suportes comparáveis, evidência rastreável e um controle de disponibilização do cálculo.')
    h('2. MATERIAL E MÉTODOS')
    p('Utilizaram-se os GeoTIFFs brazil_coverage-col11_2015.tif e brazil_coverage-col11_2025.tif, adquiridos por HTTP Range em 19/10/2026, com legenda oficial da Coleção 11 [7]. Em 20/10, os 389 intervalos utilizados coincidiram byte a byte com objetos GCS indicados pelo portal oficial [8], fixados por geração. Isso verifica os intervalos, sem autenticar o arquivo nacional inteiro ou a revisão temática; o sufixo do asset GEE não foi transferido aos GeoTIFFs.')
    p('O snapshot fixo das tabelas internas sbsr.municipios e sbsr.uf foi extraído em 19/10/2026: 167 municípios do RN e uma UF, EPSG:4326, sem reparos. Edição, provedor original, data de publicação e licença da malha continuam desconhecidos. Hashes completos, aquisição e versões estão no suplemento; data de extração não identifica edição territorial.')
    p('Somam-se áreas físicas das interseções entre pixels nativos e polígonos, sobre o elipsoide WGS84: células completas usam área por latitude; bordas usam interseção GEOS e integral de superfície com quadratura Gauss–Legendre. Não se usam overviews, interpolação de classes ou uma área constante por pixel. Conservação e um caminho independente com geodésicas densificadas [9] verificam a implementação, sem validar os mapas em campo.')
    p('Área, participação, diferença líquida, variação percentual e pontos percentuais são distintas. Participação divide área da classe pelo suporte observado; variação percentual divide a diferença pela área inicial; base zero gera null com motivo. Grupos usam união das classes folha. Comparações temporais usam a interseção das máscaras válidas reconhecidas. NoData, código desconhecido, zero real e ausência de processamento são separados. O código 0 não documentado bloqueia Areia Branca e a estatística direta da UF; 166 municípios são elegíveis. Rankings completos positivos permanecem indisponíveis.')
    blocks.append({'kind':'figure','file':'fig10_fluxo_componentes_v2.png','caption':'Figura 1. Sistema C do experimento original. O cálculo usa derivados locais; não há processamento raster durante a pergunta.'})
    p('O LLM propõe JSON; validação local resolve entidades, escopo e dados; funções permitidas calculam; o servidor publica valores e evidências. Não se executa SQL/código produzido pelo modelo. Exemplo registrado: “Em 2015, quantos hectares de Formação Florestal foram mapeados no município de Acari/RN?”. Trecho do plano: {"operation":"area","territory_codes":["2400109"],"class_codes":[3],"years":[2015],"unit":"ha"}.',citation_exempt=True)
    p(f'Operação: soma da classe folha 3 no suporte anual, m²/10.000. Resposta: “Acari/RN: {pt(example["value"]["value"])} ha de Formação Florestal em 2015”. Evidência {example["evidence"]["evidence_id"][:12]}…; execução {example["execution"]["run_id"][:12]}…. Plano completo, valor integral, método e fontes acompanham o exemplo no suplemento. É ilustração de um acerto existente.')
    p('O benchmark original separa 40 casos de desenvolvimento e 120 de teste, com 15 famílias e separação de municípios canônicos. Perguntas, gabaritos, tolerâncias, prompts e sistema foram congelados antes do teste. O autor declarou posteriormente revisar as 120 perguntas e os 88 gabaritos quantitativos, verificando território, classe, período, operação, denominador e valor, sem correções. Não informou a data efetiva da revisão nem forneceu fichas individuais ou segunda revisão independente.')
    p(f'Os gabaritos foram gerados por leitura de Parquet e Decimal independente do executor. Nesta revisão, outro recálculo direto conferiu {review["cases"]} casos e {review["value_rows"]} valores com as tolerâncias originais, sem alterar referências. Fichas geradas após a declaração mostram operandos e fórmulas; não são anotações humanas preexistentes. Esses controles compartilham os derivados e não validam verdade de campo.')
    p('Experimento original — ponta a ponta: A recebe documentação sem áreas; B recebe também todas as tabelas necessárias e gera plano/resultado; C interpreta a pergunta e usa executor/template do servidor. O contraste compara sistemas completos sob contratos diferentes. O mesmo modelo informado, RETURNED_MODEL_ID_1, usa temperatura 0 e teto de 2.048 tokens. Erros técnicos permanecem no denominador.')
    p('Experimento complementar — plano fixo: nos 88 casos quantitativos reutilizados, B_eq/C_eq recebem o mesmo plano de referência, fatos completos e esquema JSON final. Ambas geram a resposta pelo mesmo LLM; apenas C_eq recebe também o resultado do executor. Isso exclui interpretação da tarefa e controla o contrato de saída, estimando disponibilização de cálculo ao finalizador. Perguntas reutilizadas tornam o controle exploratório. Não se decompõe causalmente o ganho do experimento original.')
    blocks.append({'kind':'table','headers':['Aspecto','Original','Controle'],
        'rows':[['Entrada','Pergunta','Plano correto fornecido'],['Tarefa','Interpretação até resposta','Finalização com/sem cálculo'],
                ['Saída B/C','Contratos diferentes','Mesmo JSON pelo LLM'],['Casos','120; teste original','88 reutilizados; exploratório']],
        'caption':'Tabela 1. Dois experimentos com tarefas e alcances distintos.'})
    p('O controle foi congelado antes das novas chamadas e precedido por oito casos de desenvolvimento em cada condição. A ordem por caso foi aleatória; quatro casos por condição tiveram uma repetição separada. Para cada experimento, o IC95% usa bootstrap pareado de famílias [10], com 10.000 réplicas e seeds registradas. Correlação territorial residual e poucos grupos limitam a inferência; o IC refere-se a acerto de consulta, não a hectares.')
    h('3. RESULTADOS E DISCUSSÃO')
    h('3.1 Experimento original: ponta a ponta')
    blocks.append({'kind':'table','headers':['Condição','Acerto','Taxa','Falhas técnicas'],
        'rows':[[r['condition'],f'{r["correct"]}/{r["cases"]}',pct(r['accuracy']),str(r['technical_errors'])] for r in metrics['conditions']],
        'caption':'Tabela 2. Teste original, incluindo falhas; contratos distintos.'})
    p(f'C−B foi {pp(original["difference_C_minus_B"])} pp (IC95% [{pp(original["ci95"][0])}; {pp(original["ci95"][1])}]). O resultado inclui interpretação, validação, cálculo e publicação da resposta. As {om["B"]["technical_errors"]} falhas técnicas em B e {om["C"]["technical_errors"]} em C impedem atribuir o ganho isoladamente a raciocínio ou aritmética. A análise pós-hoc da V2 está preservada no suplemento.')
    h('3.2 Controle: resposta com plano fornecido')
    blocks.append({'kind':'figure','file':'fig15_controle_v4.png','caption':'Figura 2. Controle exploratório com plano fixo: 88 pares, oito famílias. As falhas de emissão/contrato contam como erro; os 100% de C_eq não avaliam interpretação de perguntas inéditas.'})
    p(f'B_eq acertou {cm["B_eq"]["correct"]}/88 e C_eq {cm["C_eq"]["correct"]}/88: diferença {pp(effect["difference_C_minus_B"])} pp, IC95% [{pp(effect["ci95"][0])}; {pp(effect["ci95"][1])}]. B_eq teve {errors.get(("B_eq","texto_final_ausente"),0)} retornos sem texto final e {errors.get(("B_eq","contrato_invalido"),0)} falha de contrato; C_eq teve {cm["C_eq"]["technical_errors"]} falhas técnicas. Todas as respostas emitidas estavam corretas em ambas. Assim, o ganho observado é disponibilidade/conformidade de resposta sob esse orçamento, sem erros numéricos observados nas emitidas.')
    h('3.3 Diagnóstico dos retornos sem texto')
    p('Os 26 casos se concentram em participação, variação e pontos percentuais. O cliente histórico rejeitou a ausência de texto depois de decodificar JSON de resposta 2xx; porém descartou finish_reason e usage nessa exceção. O status HTTP exato e eventuais retries também não foram registrados. Não há base para reconstruir a causa individual dos retornos antigos.')
    p(f'Um diagnóstico separado repetiu as mesmas mensagens nos 26 casos e dois controles, com limites de 2.048/4.096 tokens. Houve {lo["empty_final_text"]}/26 retornos vazios no primeiro limite e {hi["empty_final_text"]}/26 no segundo; {lo["empty_and_length"]} casos no primeiro combinaram vazio, finish_reason=length e consumo exato do teto. Todas as {diagnostic["records"]} chamadas retornaram HTTP 200, sem erro de transporte registrado. O padrão mostra sensibilidade ao orçamento nas novas chamadas, sem reconstruir causas antigas ou substituir escores.')
    blocks.append({'kind':'table','headers':['Teto de saída','Vazios','length','Texto final'],
        'rows':[[str(r['max_tokens']),f'{r["empty_final_text"]}/{r["cases"]}',str(r['finish_reason_counts'].get('length',0)),f'{r["nonempty_final_text"]}/{r["cases"]}'] for r in [lo,hi]],
        'caption':'Tabela 3. Reexecuções selecionadas pelas 26 falhas antigas; não é novo teste principal.'})
    p(f'Os contadores de entrada foram {diagnostic["input_tokens_min"]}–{diagnostic["input_tokens_max"]} tokens, iguais entre limites para cada caso. O campo de raciocínio esteve presente, mas o contador reasoning_tokens não foi informado; não se infere o esforço interno nem se armazena seu texto. Os dois controles emitiram texto nos dois limites. Sem telemetria interna, não se identifica backend, parser ou truncamento de contexto no servidor.')
    p('Disponibilidade de dados no contexto não garante uma resposta emitida dentro de um teto de geração. A melhora observada ao ampliar esse teto exige interpretar o contraste de C_eq/B_eq como dependente do orçamento e da interface, não como prova de incapacidade numérica de B_eq. O diagnóstico não altera prompts, não escolhe respostas melhores e não atualiza os 88 pares originais com reexecuções selecionadas por falha.')
    h('4. LIMITAÇÕES E CONCLUSÕES')
    p('O contraste original avalia o sistema ponta a ponta. O complementar mede fornecer cálculo ao mesmo finalizador, condicionado a plano correto e casos reutilizados. Os 100% de C_eq não estimam interpretação, generalização a perguntas inéditas ou habilidade cognitiva intrínseca. O diagnóstico mostra que o orçamento afeta a emissão; não se repetiu o controle completo a 4.096 tokens. Latência, tokens e repetibilidade limitada estão no suplemento.')
    p('Há dependência entre territórios/classes, benchmark por molduras, uma UF, dois anos, um modelo e incertezas de malha/revisão. O recálculo confirma respostas sobre os derivados; não a acurácia temática, posicional ou a verdade de campo. Mudança de classificação marginal não comprova perda bruta, causalidade ou inundação. São necessários perguntas inéditas, revisão independente e outros recortes/modelos para validade externa.')
    h('5. TRANSPARÊNCIA E AUTORIA')
    p('IA assistiu programação, construção de perguntas e redação; LLM foi objeto da avaliação. A revisão humana de perguntas/gabaritos é declaração do autor, sem fichas individuais ou concordância entre revisores. Autores reais devem confirmar contribuições, revisar o texto e assumir responsabilidade; política institucional a confirmar. [AUTORIA, AFILIAÇÕES E CONTATOS A PREENCHER].')
    h('6. REFERÊNCIAS');blocks.extend(refs);d['blocks']=blocks
    d['word_counts']={'resumo':len(d['abstract_pt'].split()),'abstract':len(d['abstract_en'].split())}
    return d


def require_human(h):
    if h['quantitative_references_reviewed']!=88 or h['corrections_reported'] or h['individual_annotations_supplied']:
        raise ValueError('declaracao_humana_fora_do_escopo_confirmado')


def report(diagnostic,review,human,controlled):
    return '\n\n'.join(['# Revisão científica V4 — material suplementar','',
        'V3 e seus escores permanecem intactos. Esta revisão acrescenta investigação separada, recálculo independente e declaração humana, sem ajustar o sistema usando resultados. Não houve submissão/publicação/deploy.',
        '## Investigação de retornos vazios',narrative(diagnostic),
        table(['Seleção','Limite de saída','Casos','Texto final','JSON válido','Vazios','Vazio e length','Uso igual ao limite'],
            [[g['selected_on'],g['max_tokens'],g['cases'],g['nonempty_final_text'],g['valid_contract'],g['empty_final_text'],g['empty_and_length'],g['completion_equals_requested_limit']] for g in diagnostic['groups']]),
        'HTTP observado nas novas chamadas: `'+json.dumps(diagnostic['http_status_counts'])+'`. Erros de transporte: `'+json.dumps(diagnostic['transport_error_counts'])+'`.',
        f'Os contadores de entrada variaram de {diagnostic["input_tokens_min"]} a {diagnostic["input_tokens_max"]} tokens e foram iguais entre os dois limites para cada caso: {diagnostic["input_tokens_same_within_case"]}. O campo de raciocínio esteve presente em {diagnostic["reasoning_field_present"]}/{diagnostic["records"]} respostas, mas seu texto não foi gravado. O contador reasoning_tokens não foi informado em {diagnostic["reasoning_token_counter_missing"]}/{diagnostic["records"]}; não se estima quantos tokens foram usados internamente.',
        table(['Hipótese','Registro histórico','Reexecução observada','Alcance da conclusão'],[
            ['Limite de saída','finish_reason/usage perdidos na exceção','length + consumo igual ao teto nos vazios; menos vazios com teto maior','Evidência de sensibilidade ao orçamento nas novas chamadas; causa antiga individual não recuperada'],
            ['Timeout','Erro registrado foi texto_final_ausente, não timeout','Nenhum erro de transporte/timeout capturado','Não foi a falha observada nos replays; não reconstrói eventos internos antigos'],
            ['HTTP/gateway','Status exato e retries ausentes; final 2xx inferido do código','Todos os chats HTTP 200, sem retries capturados','Sem erro HTTP observado no diagnóstico; não identifica backend/parser'],
            ['Truncamento da resposta na rede/cliente','Não há corpo preservado','JSON completo; wrapper conta bytes; sem erro de leitura registrado','Sem truncamento de transporte observado; distinto de término por limite de geração'],
            ['Entrada/contexto','Mensagens reconstruíveis por hash; sem usage nos vazios','Mesmo hash e mesmos contadores de entrada entre limites','Não permite provar a ausência de truncamento interno do servidor'],
            ['Formato das mensagens','Contrato textual de dois papéis confirmado no código','Mesmas mensagens, sem mudar formatos ou endpoints','Não se testou formato alternativo; implementação interna permanece desconhecida']]),
        'As mensagens iniciais foram reconstruídas e conferidas por hash contra B_eq. O wrapper preserva metadados mesmo quando o cliente original rejeita texto vazio. Registram-se somente estados/contadores, sem texto de raciocínio, corpo HTTP, tokens OAuth2 ou Authorization. Não houve teste de outro formato de mensagens, API, modelo, seed ou esforço de raciocínio.',
        'Não se conclui ausência histórica de erros HTTP a partir de status null. O caminho de código permite inferir somente resposta final 2xx/JSON antes da rejeição; retries intermediários não estão nos logs antigos. Da mesma forma, presença de campo de raciocínio não mede tokens internos: o contador fica null se não informado.',
        'A documentação primária do modelo descreve seu formato Harmony e separação de canais ([repositório oficial gpt-oss](https://github.com/openai/gpt-oss/blob/main/README.md), consultado em 21/10/2026). Isso contextualiza a necessidade de distinguir texto final e outros campos, sem identificar o backend, versão, parser ou configuração interna do LLM. Não se infere um bug do gateway dessa documentação.',
        'Uma replicação com novos casos e orçamento predefinido em ambos os braços seria necessária para estimar o contraste sob outro teto. Não se atualiza o acerto principal usando replays selecionados pelas falhas, nem se ajustam prompts ou produção com base neles.',
        *diagnostic['limitations'],
        '## Revisão humana dos gabaritos',
        'O autor confirmou: “'+human['statement']+'”. A pergunta de esclarecimento explicitou território, classe, período, operação, denominador e valor. A declaração recebida em 21/10/2026 cobre todos os 88 casos quantitativos, identificados por hashes. Não foram alterados perguntas, gabaritos ou escores. Não foi informada a data efetiva da revisão, nem fornecidas fichas originais ou segunda revisão independente.',
        f'O recálculo automático adicional usou DuckDB apenas para ler Parquet verificado por hash e fórmulas Decimal em outro módulo, sem executor nem oráculo anterior. Foram conferidos {review["cases"]} casos e {review["value_rows"]} valores; aprovação integral: {review["all_passed"]}. Tolerâncias são as originais e referem-se à representação, não à incerteza ambiental.',
        'FICHAS_88_GABARITOS.md e fichas_88.json documentam folhas unidas, território, anos, suporte, operandos, fórmula, denominadores, referência e valor recalculado. Essas fichas foram geradas depois da declaração e não são apresentadas como anotações humanas anteriores.',
        '## Dois experimentos, duas interpretações',
        table(['Aspecto','Original A/B/C','Complementar B_eq/C_eq'],[
            ['Entrada','Pergunta e contexto','Pergunta, contexto e plano correto fornecido'],
            ['Tarefa','Interpretação, validação, cálculo e resposta','Finalização com/sem cálculo disponível'],
            ['Contrato','B plano/resultado; C proposta + executor/template','Mesmo JSON final gerado pelo mesmo LLM'],
            ['Casos','120 testes; famílias separadas do desenvolvimento','88 quantitativos reutilizados; exploratório'],
            ['100% de C_eq','Não se aplica','Condicionado ao plano e orçamento; não pergunta inédita'],
            ['Estimando','Diferença entre sistemas completos','Efeito operacional de disponibilizar cálculo ao finalizador']]),
        'O diagnóstico novo tem amostra selecionada por falhas e outro orçamento; não fornece uma terceira estimativa de acerto principal, não substitui casos, e não identifica qual parcela do contraste original é causada pelo executor.',
        '## Suplemento preservado e limites',
        'As tabelas originais de latência/tokens, bootstrap por famílias, proveniência do espelho, malha, legenda, código e uso de IA permanecem nos arquivos V3 copiados sem alterar valores. O material V4 destaca o controle no texto e move pormenores operacionais para este suplemento. Custos ausentes continuam null; reprodução remota não é determinismo garantido.',
        'Persistem edição/licença/provedor da malha desconhecidos e revisão temática não autenticada. Não há validação de campo ou alegação de superioridade geral. Autoria/afiliações seguem pendentes e publicação dos artefatos depende de direitos.'])+'\n'
